class MiComponente extends HTMLElement {
  static observedAttributes = ['titulo'];

  connectedCallback() {
    this.render();
  }

  disconnectedCallback() {
    // Limpiar listeners o temporizadores
  }

  attributeChangedCallback(nombre, anterior, nuevo) {
    if (anterior !== nuevo && this.isConnected) this.render();
  }

  render() {
    this.textContent = this.getAttribute('titulo') || 'Sin título';
  }
}

customElements.define('mi-componente', MiComponente);

examples.code:
class MiBotonRegistro extends HTMLElement {
  constructor() {
    super();
    this.manejarClick = () => console.log('Se pulsó el componente');
  }

  connectedCallback() {
    this.addEventListener('click', this.manejarClick);
    this.textContent = 'Pulsame';
  }

  disconnectedCallback() {
    this.removeEventListener('click', this.manejarClick);
  }
}

customElements.define('mi-boton-registro', MiBotonRegistro);

class MiTitulo extends HTMLElement {
  static observedAttributes = ['titulo'];

  connectedCallback() {
    this.actualizar();
  }

  attributeChangedCallback(nombre, valorAnterior, valorNuevo) {
    if (valorAnterior !== valorNuevo && this.isConnected) {
      this.actualizar();
    }
  }

  actualizar() {
    this.textContent = this.getAttribute('titulo') || 'Título sin definir';
  }
}

customElements.define('mi-titulo', MiTitulo);

// HTML: <mi-titulo titulo="Primer título"></mi-titulo>
// Luego: document.querySelector('mi-titulo').setAttribute('titulo', 'Nuevo título');

class MiCronometro extends HTMLElement {
  constructor() {
    super();
    this.segundos = 0;
    this.intervalo = null;
  }

  connectedCallback() {
    if (this.intervalo !== null) return;
    this.intervalo = setInterval(() => {
      this.segundos += 1;
      this.textContent = 'Segundos: ' + this.segundos;
    }, 1000);
  }

  disconnectedCallback() {
    clearInterval(this.intervalo);
    this.intervalo = null;
  }
}

customElements.define('mi-cronometro', MiCronometro);

class MiRegistroDocumento extends HTMLElement {
  adoptedCallback() {
    console.log('El componente ahora pertenece a otro documento.');
  }
}

customElements.define('mi-registro-documento', MiRegistroDocumento);

const componente = document.createElement('mi-registro-documento');
document.body.append(componente);

const otroDocumento = document.implementation.createHTMLDocument('Documento secundario');
otroDocumento.adoptNode(componente);

