class MiListaSlots extends HTMLElement {
  constructor() {
    super();
    const root = this.attachShadow({ mode: 'open' });
    root.innerHTML = '<section><slot name="item"></slot><p id="cantidad"></p></section>';
    const slot = root.querySelector('slot');
    const salida = root.querySelector('#cantidad');
    const actualizar = () => {
      salida.textContent = 'Elementos asignados: ' + slot.assignedElements().length;
    };
    slot.addEventListener('slotchange', actualizar);
    actualizar();
  }
}

customElements.define('mi-lista-slots', MiListaSlots);

// HTML inicial: <mi-lista-slots><span slot="item">Uno</span></mi-lista-slots>
// Luego podés agregar otro hijo con slot="item".

class MiContenidoAsignado extends HTMLElement {
  constructor() {
    super();
    const root = this.attachShadow({ mode: 'open' });
    root.innerHTML = '<div><slot name="contenido"></slot></div>';
    const slot = root.querySelector('slot');
    slot.addEventListener('slotchange', () => {
      const elementos = slot.assignedElements({ flatten: true });
      console.log('Elementos recibidos:', elementos);
    });
  }
}

customElements.define('mi-contenido-asignado', MiContenidoAsignado);

// HTML: <mi-contenido-asignado>
//   <strong slot="contenido">Texto importante</strong>
