class MiSelectorSimple extends HTMLElement {
  constructor() {
    super();
    this.seleccionar = () => {
      this.dispatchEvent(new CustomEvent('color-seleccionado', {
        detail: { color: 'azul' },
        bubbles: true
      }));
    };
  }

  connectedCallback() {
    this.textContent = 'Elegir azul';
    this.addEventListener('click', this.seleccionar);
  }

  disconnectedCallback() {
    this.removeEventListener('click', this.seleccionar);
  }
}

customElements.define('mi-selector-simple', MiSelectorSimple);

document.addEventListener('color-seleccionado', evento => {
  console.log('Color elegido:', evento.detail.color);
});

// HTML: <mi-selector-simple></mi-selector-simple>

class MiSelectorSombra extends HTMLElement {
  constructor() {
    super();
    const root = this.attachShadow({ mode: 'open' });
    const boton = document.createElement('button');
    boton.textContent = 'Elegir verde';
    boton.addEventListener('click', () => {
      boton.dispatchEvent(new CustomEvent('color-seleccionado', {
        detail: { color: 'verde' },
        bubbles: true,
        composed: true
      }));
    });
    root.append(boton);
  }
}

customElements.define('mi-selector-sombra', MiSelectorSombra);

document.addEventListener('color-seleccionado', evento => {
  console.log(evento.detail.color);
  console.log('Anfitrión visible desde afuera:', evento.target);
});

class MiProductoSeleccionable extends HTMLElement {
  connectedCallback() {
    this.textContent = 'Agregar teclado';
    this.addEventListener('click', () => {
      this.dispatchEvent(new CustomEvent('producto-agregado', {
        detail: {
          id: 42,
          nombre: 'Teclado',
          cantidad: 1
        },
        bubbles: true
      }));
    });
  }
}

customElements.define('mi-producto-seleccionable', MiProductoSeleccionable);

document.addEventListener('producto-agregado', evento => {
  const producto = evento.detail;
  console.log(producto.id, producto.nombre, producto.cantidad);
});

class MiAccionCancelable extends HTMLElement {
  connectedCallback() {
    this.textContent = 'Intentar eliminar';
    this.addEventListener('click', () => {
      const permitido = this.dispatchEvent(new CustomEvent('antes-de-eliminar', {
        detail: { id: 17 },
        bubbles: true,
        cancelable: true
      }));

      if (permitido) {
        console.log('Se continúa con la eliminación');
      } else {
        console.log('La eliminación fue cancelada');
      }
    });
  }
}

customElements.define('mi-accion-cancelable', MiAccionCancelable);

document.addEventListener('antes-de-eliminar', evento => {
  const confirmar = confirm('¿Seguro que querés continuar?');
  if (!confirmar) evento.preventDefault();
});

class SelectorNovela extends HTMLElement {
  constructor() {
    super();
    const root = this.attachShadow({ mode: 'open' });
    const boton = document.createElement('button');
    boton.textContent = 'Elegir Re:Zero';
    boton.addEventListener('click', () => {
      const evento = new CustomEvent('novela-seleccionada', {
        detail: { slug: 're-zero' },
        bubbles: true,
        composed: true
      });
      boton.dispatchEvent(evento);
    });
    root.append(boton);
  }
}

customElements.define('selector-novela', SelectorNovela);

document.addEventListener('novela-seleccionada', evento => {
  console.log(evento.detail.slug);
});
